class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int n = gas.length;
        for (int start = 0; start < n; start++) {
            int tank = 0;
            boolean ok = true;
            for (int step = 0; step < n; step++) {
                int i = (start + step) % n;       // 环形取模
                tank += gas[i] - cost[i];
                if (tank < 0) { ok = false; break; } // 中途没油了
            }
            if (ok) return start;
        }
        return -1;
    }
}

class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int n = gas.length;
        int totalGas = 0, totalCost = 0;
        int start = 0, tank = 0;
        for (int i = 0; i < n; i++) {
            totalGas += gas[i];
            totalCost += cost[i];
            tank += gas[i] - cost[i];   // 当前净增益
            if (tank < 0) {             // 从 start 到 i 走不通
                start = i + 1;          // 起点跳到 i+1
                tank = 0;               // 油箱重新从空算起
            }
        }
        return totalGas >= totalCost ? start : -1;
    }
}

class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int total = 0, tank = 0, start = 0;
        for (int i = 0; i < gas.length; i++) {
            int diff = gas[i] - cost[i];
            total += diff;
            tank += diff;
            if (tank < 0) {
                start = i + 1;   // 跳过失败区间，起点后移
                tank = 0;
            }
        }
        return total >= 0 ? start : -1;
    }
}

