输入：
["MinStack","push","push","push","getMin","pop","top","getMin"]
[[],[-2],[0],[-3],[],[],[],[]]

输出：
[null,null,null,null,-3,null,0,-2]

MinStack minStack = new MinStack();
minStack.push(-2);
minStack.push(0);
minStack.push(-3);
minStack.getMin();   // 返回 -3
minStack.pop();
minStack.top();      // 返回 0
minStack.getMin();   // 返回 -2

// 伪代码：getMin 时遍历整个栈找最小
public int getMin() {
    int min = Integer.MAX_VALUE;
    for (int v : stack) min = Math.min(min, v);
    return min;
}

class MinStack {
    private Deque<Integer> stack;   // 主栈
    private Deque<Integer> minStack; // 辅助栈：栈顶始终是当前最小值

    public MinStack() {
        stack = new ArrayDeque<>();
        minStack = new ArrayDeque<>();
    }

    public void push(int val) {
        stack.push(val);
        // 辅助栈压「当前最小值」：val 更小或相等则压 val，否则压旧最小
        if (minStack.isEmpty() || val <= minStack.peek()) {
            minStack.push(val);
        } else {
            minStack.push(minStack.peek());
        }
    }

    public void pop() {
        stack.pop();
        minStack.pop();   // 同步弹出，最小值随之回退
    }

    public int top() {
        return stack.peek();
    }

    public int getMin() {
        return minStack.peek();
    }
}

class MinStack {
    // 用两个并行栈，或一个存 Node 的栈
    private Deque<Integer> stack;
    private Deque<Integer> minStack; // 与 stack 严格等长，minStack[i] = push 第 i 个元素时的全局最小

    public MinStack() {
        stack = new ArrayDeque<>();
        minStack = new ArrayDeque<>();
    }

    public void push(int val) {
        stack.push(val);
        int curMin = minStack.isEmpty() ? val : Math.min(val, minStack.peek());
        minStack.push(curMin);
    }

    public void pop() {
        stack.pop();
        minStack.pop();
    }

    public int top() {
        return stack.peek();
    }

    public int getMin() {
        return minStack.peek();
    }
}

