class Solution {
    public int[] twoSum(int[] numbers, int target) {
        int n = numbers.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (numbers[i] + numbers[j] == target) {
                    return new int[]{i + 1, j + 1}; // 下标从 1 开始
                }
            }
        }
        return new int[]{-1, -1};
    }
}

class Solution {
    public int[] twoSum(int[] numbers, int target) {
        int n = numbers.length;
        for (int i = 0; i < n; i++) {
            int need = target - numbers[i];
            int left = i + 1, right = n - 1;     // 只在 i 右侧二分
            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (numbers[mid] == need) {
                    return new int[]{i + 1, mid + 1};
                } else if (numbers[mid] < need) {
                    left = mid + 1;               // 偏小，往右
                } else {
                    right = mid - 1;              // 偏大，往左
                }
            }
        }
        return new int[]{-1, -1};
    }
}

class Solution {
    public int[] twoSum(int[] numbers, int target) {
        int left = 0, right = numbers.length - 1;
        while (left < right) {
            int sum = numbers[left] + numbers[right];
            if (sum == target) {
                return new int[]{left + 1, right + 1};
            } else if (sum < target) {
                left++;    // 和太小：左指针右移，让和变大
            } else {
                right--;   // 和太大：右指针左移，让和变小
            }
        }
        return new int[]{-1, -1};
    }
}

